  id: number;
  name: string;
  shortName: string;
  abbrev: string;
  logo: string | null;
  color: string | null;
  altColor: string | null;
  conference: string | null;
  record: string | null;
  confRecord: string | null;
  homeRecord: string | null;
  awayRecord: string | null;
  vsApRecord: string | null;
  playoffSeed: number | null;
  apRank: number | null;
  coachesRank: number | null;
  srsRank: number | null;
